# -*- coding: utf-8 -*-
"""Bổ sung Quyển 1 - Chương 1: 20 trắc nghiệm (12 medium + 8 hard), 3 trả lời ngắn, 1 tự luận."""

MCQ = [
    ("medium", r"Chức năng nào sau đây KHÔNG phải là chức năng cốt lõi của một Hệ quản trị CSDL (DBMS)?",
     [r"Quản lý từ điển dữ liệu (catalog)", r"Điều khiển truy xuất đồng thời nhiều người dùng",
      r"Tự động thiết kế giao diện đồ họa riêng cho từng ứng dụng khách", r"Sao lưu và phục hồi sau sự cố"],
     "C", r"DBMS cung cấp DDL/DML/DCL, catalog, điều khiển đồng thời, an toàn và phục hồi. Thiết kế giao diện ứng dụng là việc của lập trình viên ứng dụng, không phải chức năng của DBMS."),
    ("medium", r"Câu lệnh `TRUNCATE TABLE DONHANG` thuộc nhóm ngôn ngữ nào của SQL?",
     [r"DML", r"DDL", r"DCL", r"DQL"],
     "B", r"`TRUNCATE` tác động lên cấu trúc lưu trữ của bảng (giải phóng toàn bộ trang dữ liệu) nên được xếp vào DDL, khác với `DELETE` là DML."),
    ("medium", r"Các lệnh `COMMIT`, `ROLLBACK`, `SAVEPOINT` thuộc nhóm nào?",
     [r"DDL - định nghĩa dữ liệu", r"DML - thao tác dữ liệu", r"DCL - phân quyền", r"TCL - điều khiển giao dịch"],
     "D", r"Đây là nhóm TCL (Transaction Control Language), dùng để xác nhận hoặc hủy các thay đổi của một giao dịch."),
    ("medium", r"Giao dịch chuyển 1 triệu từ tài khoản A sang B: đã trừ A xong thì hệ thống sập trước khi cộng B. Để không mất tiền, DBMS phải hủy phép trừ A. Đây là biểu hiện của tính chất nào?",
     [r"Atomicity (nguyên tử)", r"Isolation (cô lập)", r"Durability (bền vững)", r"Consistency (nhất quán) nhưng không liên quan đến nguyên tử"],
     "A", r"Atomicity: giao dịch là 'tất cả hoặc không có gì'. Hủy phép trừ dở dang bảo đảm tính nguyên tử."),
    ("medium", r"Sau khi giao dịch đã `COMMIT` thành công, máy chủ bị mất điện. Khi khởi động lại, dữ liệu của giao dịch đó vẫn còn. Đây là tính chất nào?",
     [r"Atomicity", r"Isolation", r"Durability", r"Consistency"],
     "C", r"Durability (bền vững): kết quả của giao dịch đã commit phải được lưu vĩnh viễn, thường nhờ nhật ký giao tác (log) ghi xuống đĩa."),
    ("medium", r"Giao dịch T1 đang sửa `SoDu` nhưng CHƯA commit; giao dịch T2 đọc được giá trị tạm thời đó. Tính chất ACID nào bị vi phạm?",
     [r"Durability", r"Isolation", r"Atomicity", r"Consistency"],
     "B", r"T2 nhìn thấy dữ liệu trung gian của T1 (dirty read) nghĩa là các giao dịch không được cô lập với nhau, vi phạm Isolation."),
    ("medium", r"Bảng `TAIKHOAN` có ràng buộc `CHECK (SoDu >= 0)`. Một giao dịch rút tiền làm `SoDu` âm nên bị từ chối. Tính chất nào của giao dịch được bảo vệ?",
     [r"Durability", r"Atomicity", r"Isolation", r"Consistency"],
     "D", r"Consistency: giao dịch chỉ được đưa CSDL từ trạng thái hợp lệ sang trạng thái hợp lệ, nên mọi ràng buộc toàn vẹn phải được thỏa mãn."),
    ("medium", r"Một khung nhìn (VIEW) `V_SV_CNTT` chỉ hiển thị sinh viên khoa CNTT thuộc mức nào trong kiến trúc ANSI/SPARC?",
     [r"Mức ngoài", r"Mức khái niệm", r"Mức trong", r"Mức vật lý của hệ điều hành"],
     "A", r"VIEW là lược đồ ngoài: biểu diễn dữ liệu theo nhu cầu và thẩm quyền của một nhóm người dùng."),
    ("medium", r"DBA tạo thêm chỉ mục `CREATE INDEX idx_hoten ON SINHVIEN(HoTen)`. Việc này tác động trực tiếp tới mức nào?",
     [r"Mức ngoài", r"Mức khái niệm", r"Mức trong (vật lý)", r"Cả ba mức một cách như nhau"],
     "C", r"Chỉ mục là cấu trúc truy xuất vật lý, thuộc lược đồ trong. Lược đồ khái niệm (bảng, cột, ràng buộc) không đổi."),
    ("medium", r"Thông tin 'cột `HoTen` của bảng `SINHVIEN` có kiểu `NVARCHAR(100)` và `NOT NULL`' được lưu ở đâu và gọi là gì?",
     [r"Trong bảng `SINHVIEN`, gọi là dữ liệu người dùng", r"Trong từ điển dữ liệu, gọi là siêu dữ liệu (metadata)",
      r"Trong chương trình ứng dụng, gọi là mã nguồn", r"Trong tệp nhật ký, gọi là thể hiện"],
     "B", r"Mô tả cấu trúc dữ liệu là metadata và được DBMS lưu trong catalog (từ điển dữ liệu)."),
    ("medium", r"Khái niệm nào đúng với 'thể hiện' (instance/state) của CSDL?",
     [r"Tập tên bảng, tên cột và kiểu dữ liệu", r"Tập các ràng buộc toàn vẹn của CSDL",
      r"Bản thiết kế ER của hệ thống", r"Tập dữ liệu thực sự đang có trong CSDL tại một thời điểm"],
     "D", r"Lược đồ là cấu trúc tĩnh; thể hiện là nội dung dữ liệu tại một thời điểm và thay đổi qua mỗi thao tác DML."),
    ("medium", r"Nguyên nhân gốc của 'dị thường cập nhật' (cùng một thông tin ở nhiều nơi, sửa chỗ này quên chỗ kia) trong cách tiếp cận hệ thống tệp là gì?",
     [r"Dư thừa dữ liệu (redundancy)", r"Thiếu bộ nhớ RAM", r"Tốc độ đĩa chậm", r"Thiếu giao diện đồ họa"],
     "A", r"Dữ liệu trùng lặp ở nhiều tệp khiến việc cập nhật không đồng bộ, dẫn tới bất nhất."),

    ("hard", r"Vì sao độc lập dữ liệu logic thường khó đạt được hơn độc lập dữ liệu vật lý?",
     [r"Vì phần cứng đĩa luôn thay đổi nhanh hơn phần mềm",
      r"Vì các ứng dụng phụ thuộc trực tiếp vào cấu trúc logic (tên bảng, tên cột, quan hệ), nên thay đổi lược đồ khái niệm dễ lan sang ứng dụng",
      r"Vì DBMS không hỗ trợ ánh xạ giữa mức ngoài và mức khái niệm",
      r"Vì lược đồ trong luôn trùng với lược đồ ngoài"],
     "B", r"Độc lập vật lý chỉ cần DBMS tự chọn cách truy xuất; độc lập logic đòi hỏi cập nhật ánh xạ/view để che chắn ứng dụng khỏi thay đổi lược đồ."),
    ("hard", r"Khi đổi tên cột `MaSV` thành `MSSV` ở mức khái niệm mà vẫn muốn ứng dụng mức ngoài chạy nguyên vẹn, cần làm gì?",
     [r"Viết lại toàn bộ ứng dụng", r"Xóa bảng rồi tạo lại và nhập lại dữ liệu",
      r"Cập nhật định nghĩa view/ánh xạ ngoài-khái niệm để view cũ vẫn trả về cột tên `MaSV`", r"Không thể thực hiện được"],
     "C", r"Đây chính là vai trò của ánh xạ ngoài - khái niệm: chỉ sửa định nghĩa view (alias `MSSV AS MaSV`), ứng dụng không phải đổi."),
    ("hard", r"Phát biểu nào về số lượng lược đồ trong kiến trúc ANSI/SPARC là SAI?",
     [r"Mỗi CSDL có đúng một lược đồ ngoài", r"Mỗi CSDL có một lược đồ khái niệm",
      r"Mỗi CSDL có một lược đồ trong", r"Có thể có nhiều lược đồ ngoài cho các nhóm người dùng khác nhau"],
     "A", r"Mỗi nhóm người dùng có thể có lược đồ ngoài riêng, nên số lược đồ ngoài thường nhiều hơn một."),
    ("hard", r"T1 và T2 cùng đọc `SoDu = 100`, T1 ghi lại 150 (100+50), T2 cũng ghi lại 150 (100+50). Kết quả đúng phải là 200. Đây là hiện tượng gì và vi phạm tính chất nào?",
     [r"Dirty read, vi phạm Durability", r"Deadlock, vi phạm Atomicity",
      r"Phantom, vi phạm Consistency của ràng buộc khóa chính", r"Lost update (mất cập nhật), vi phạm Isolation"],
     "D", r"Hai giao dịch xen kẽ không kiểm soát khiến một cập nhật bị ghi đè. Giao dịch phải cô lập sao cho kết quả tương đương thực thi tuần tự."),
    ("hard", r"'Độc lập giữa chương trình và dữ liệu' (program-data independence), ưu điểm của cách tiếp cận CSDL, có nghĩa là gì?",
     [r"Chương trình không bao giờ cần truy cập dữ liệu", r"Mô tả cấu trúc dữ liệu được tách khỏi chương trình và lưu trong catalog, nên đổi cấu trúc không buộc sửa mọi chương trình",
      r"Dữ liệu được lưu trong mã nguồn chương trình", r"Mỗi chương trình tự quản lý một tệp dữ liệu riêng"],
     "B", r"Trong hệ thống tệp, cấu trúc bản ghi nằm cứng trong từng chương trình; trong CSDL, cấu trúc nằm ở catalog và được dùng chung."),
    ("hard", r"DBA chuyển bảng `GIAODICH` sang phân vùng theo năm trên các ổ đĩa khác nhau; mọi câu SQL của ứng dụng vẫn giữ nguyên. Đây là minh họa của:",
     [r"Độc lập dữ liệu logic", r"Tính nhất quán dữ liệu", r"Độc lập dữ liệu vật lý", r"Tính toàn vẹn tham chiếu"],
     "C", r"Chỉ thay đổi cách lưu trữ vật lý (lược đồ trong), lược đồ khái niệm và ứng dụng không đổi."),
    ("hard", r"Một view có cột suy diễn `TongTien = SoLuong * DonGia`. Phát biểu nào đúng nhất?",
     [r"Cột `TongTien` bắt buộc phải được lưu vật lý ở mức trong như mọi cột khác",
      r"Cột `TongTien` được tính từ dữ liệu mức khái niệm khi truy vấn view, không nhất thiết lưu riêng",
      r"View làm thay đổi lược đồ khái niệm của CSDL",
      r"Không thể tạo cột suy diễn trong view"],
     "B", r"View là lược đồ ngoài; biểu thức được tính khi truy vấn qua ánh xạ ngoài - khái niệm, thường không lưu vật lý (trừ materialized view)."),
    ("hard", r"Thứ tự xử lý đúng khi người dùng gửi một câu SQL truy vấn trên một view là:",
     [r"Mức trong -> mức khái niệm -> mức ngoài -> kết quả", r"Mức khái niệm -> mức ngoài -> mức trong -> kết quả",
      r"Truy xuất đĩa -> dịch SQL -> ánh xạ -> kết quả", r"Ánh xạ ngoài -> khái niệm, rồi khái niệm -> trong, sau đó truy xuất đĩa và trả kết quả ngược lại"],
     "D", r"Yêu cầu đi từ mức ngoài xuống mức trong qua hai lần ánh xạ, dữ liệu được đọc từ đĩa rồi biến đổi ngược lên thành kết quả cho người dùng."),
]

SHORT = [
    (r"Phân biệt DELETE, TRUNCATE và DROP TABLE về nhóm lệnh và phạm vi tác động.",
     r"- `DELETE`: DML, xóa từng dòng (có thể có `WHERE`), ghi log từng dòng, có thể rollback.\n- `TRUNCATE`: DDL, xóa toàn bộ dòng, giải phóng trang dữ liệu, nhanh, giữ cấu trúc bảng.\n- `DROP TABLE`: DDL, xóa cả cấu trúc bảng lẫn dữ liệu và ràng buộc.".replace(r"\n", "\n"),
     r"Chỉ `DELETE` có điều kiện `WHERE`; `DROP` làm mất định nghĩa bảng khỏi catalog."),
    (r"Nêu 3 lợi ích của việc quản lý dữ liệu tập trung bằng DBMS so với hệ thống tệp truyền thống.",
     r"(1) Giảm dư thừa và bất nhất dữ liệu; (2) Chia sẻ dữ liệu và kiểm soát truy xuất đồng thời; (3) Bảo mật, phân quyền, sao lưu/phục hồi và ràng buộc toàn vẹn tập trung.",
     r"Có thể kể thêm: độc lập chương trình - dữ liệu, truy vấn khai báo bằng SQL."),
    (r"Tại sao nói 'từ điển dữ liệu' (catalog) bản thân cũng là một CSDL?",
     r"Vì catalog lưu siêu dữ liệu của CSDL dưới dạng các bảng hệ thống (danh sách bảng, cột, khóa, chỉ mục, quyền...) và có thể được truy vấn bằng SQL như bảng thường.",
     r"Ví dụ: `INFORMATION_SCHEMA.TABLES`, `sys.columns` trong SQL Server."),
]

ESSAY = [
    (r"Phân tích tính chất ACID qua kịch bản chuyển khoản liên ngân hàng",
     r"Giao dịch `CHUYENKHOAN(A -> B, 5.000.000)` gồm 3 bước: (1) kiểm tra `SoDu(A) >= 5.000.000`; (2) trừ `SoDu(A)`; (3) cộng `SoDu(B)`. Hãy: a) chỉ ra mỗi thuộc tính A, C, I, D thể hiện thế nào; b) nêu hậu quả khi từng thuộc tính bị vi phạm; c) viết khung giao dịch T-SQL bảo đảm tính nguyên tử.",
     [r"Bước 1 - A (Atomicity): cả ba bước cùng thành công hoặc cùng bị hủy. Nếu sập sau bước 2 mà trước bước 3, hệ thống phải rollback phép trừ, nếu không 5 triệu 'bốc hơi'.",
      r"Bước 2 - C (Consistency): ràng buộc `SoDu >= 0` và tổng tiền hệ thống không đổi. Nếu A không đủ tiền, giao dịch phải bị từ chối, CSDL vẫn ở trạng thái hợp lệ.",
      r"Bước 3 - I (Isolation): nếu hai giao dịch cùng rút từ A, kết quả phải như thực thi tuần tự. Vi phạm sẽ gây lost update hoặc dirty read, ví dụ A bị trừ 2 lần dựa trên cùng số dư cũ.",
      r"Bước 4 - D (Durability): sau COMMIT, dù mất điện, thay đổi vẫn được phục hồi từ nhật ký giao tác (write-ahead log).",
      "Bước 5 - Khung T-SQL:\n```sql\nBEGIN TRY\n  BEGIN TRANSACTION;\n    IF (SELECT SoDu FROM TAIKHOAN WHERE SoTK='A') < 5000000\n       THROW 50001, N'Không đủ số dư', 1;\n    UPDATE TAIKHOAN SET SoDu = SoDu - 5000000 WHERE SoTK='A';\n    UPDATE TAIKHOAN SET SoDu = SoDu + 5000000 WHERE SoTK='B';\n  COMMIT TRANSACTION;\nEND TRY\nBEGIN CATCH\n  ROLLBACK TRANSACTION;\n  THROW;\nEND CATCH\n```",
      r"Kết luận: `BEGIN/COMMIT/ROLLBACK` bảo đảm A; CHECK/FK bảo đảm C; cơ chế khóa/MVCC bảo đảm I; log bảo đảm D."]),
]
